import (
	"fmt"
)

resp, err := client.ProductPageSettings().GetProductPage(ctx, nil, nil)
if err != nil {
	log.Fatal(err)
}
settings := resp.Map().(map[string]any)["product_page"].(map[string]any)
details := settings["configuration"].(map[string]any)["details"].(map[string]any)
upSell := settings["up_sell"].(map[string]any)
fmt.Println(details["display_description"], upSell["number_of_products"], upSell["short_description"])

