	"fmt"
)

resp, err := client.ProductPageSettings().PatchProductPage(ctx, map[string]any{
	"product_page": map[string]any{
		"configuration": map[string]any{"details": map[string]any{"display_description": true}},
		"up_sell":       map[string]any{"short_description": true},
	},
}, nil)
if err != nil {
	log.Fatal(err)
}
settings := resp.Map().(map[string]any)["product_page"].(map[string]any)
details := settings["configuration"].(map[string]any)["details"].(map[string]any)
fmt.Println(details["display_description"], settings["up_sell"].(map[string]any)["short_description"])

